style.css:
@-moz-document domain("roblox.com") {
/* === Global Background === */
    html, body {
        background: url("https://assets.userstyles.org/assets_packs/type=style/user_id=3305835/screenshot_e81b6a55-9979-46d0-8e67-56a47ced55dc.webp") no-repeat center center fixed !important;
        background-size: cover !important;
        color: #ffffff !important;
        font-family: "Segoe UI", sans-serif !important;
        scroll-behavior: smooth;
    }

    /* === Overlay to Darken Page Slightly === */
    body::before {
        content: "";
        position: fixed;
        top: 0; left: 0; right: 0; bottom: 0;
        background: rgba(0, 0, 0, 0.7);
        z-index: -1;
    }

    /* === Smooth Container Styling === */
    .container-fluid, .content, .section, .navbar, .header, .footer,
    .rbx-navbar, .rbx-header, .rbx-footer, 
    .modal-content, .dropdown-menu, 
    .game-card, .thumbnail-2d-container {
        background: rgba(20, 20, 20, 0.6) !important;
        border-radius: 12px !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
        box-shadow: 0 0 10px rgba(0, 255, 255, 0.05) !important;
        backdrop-filter: blur(8px) !important;
        transition: all 0.3s ease;
    }

    /* === Buttons and Hover Effects === */
    a, .btn, button {
        background: rgba(0, 255, 255, 0.15) !important;
        color: #fff !important;
        border: 1px solid rgba(0, 255, 255, 0.3) !important;
        border-radius: 8px !important;
        padding: 6px 12px !important;
        transition: all 0.2s ease-in-out;
    }

    a:hover, .btn:hover, button:hover {
        background: rgba(0, 255, 255, 0.3) !important;
        color: #0ff !important;
        box-shadow: 0 0 8px #0ff !important;
    }

    /* === Inputs, Forms === */
    input, textarea, select {
        background: rgba(255, 255, 255, 0.08) !important;
        color: #fff !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        border-radius: 6px !important;
        padding: 6px !important;
    }

    input::placeholder, textarea::placeholder {
        color: #ccc !important;
    }

    /* === Fixes for Text Colors === */
    .text-muted, .text-secondary, .label, .small, 
    .rbx-text-secondary, .font-caption-header {
        color: #ccc !important;
    }

    /* === Game Thumbnails & Images === */
    .game-card-thumb, img {
        border-radius: 10px !important;
        box-shadow: 0 0 6px rgba(0, 255, 255, 0.2) !important;
        transition: transform 0.2s ease;
    }

    .game-card-thumb:hover, img:hover {
        transform: scale(1.02);
    }

    /* === Scrollbar Styling === */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: rgba(255, 255, 255, 0.05);
    }

    ::-webkit-scrollbar-thumb {
        background: rgba(0, 255, 255, 0.3);
        border-radius: 5px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #0ff;
    }

    /* === Hide Roblox Light Theme Overlays === */
    .light-theme, .theme-light {
        background: transparent !important;
    }
}
